using System;

namespace StdbModule;

public static partial class ArabicQuotes
{
    public static class جبرانخليلجبران
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن السماء لا تريد أن يكون الإنسان تعسًا؛ لأنها وضعت في أعماقه الميل إلى السعادة؛ لأنه بسعادة الإنسان يتمجد الله.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أن نقابل الشر بشر أعظم ونقول هذه هي الشريعة، ونقاتل الفساد بفساد أعم، ونهتف هذا هو الناموس، ونغالب الجريمة بجريمة أكبر، ونصرخ هو العدل؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "نفوسكم في قبضة الكاهن، وأجسادكم بين مخالب الحاكم، وقلوبكم في ظلمة اليأس والأحزان، فأي شيء في الحياة يمكنكم أن تشيروا إليه قائلين: «هذا لنا.»", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الله قد بعث أرواحكم في هذه الحياة كشعلات مضيئة تنمو بالمعرفة وتزيد جمالًا باستطلاعها خفايا الأيام والليالي فكيف تلحقونها بالرماد لتبيد وتنطفيء.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الله قد وهب نفوسكم أجنحة لتطير بها سابحة في فضاء الحب والحرية فلماذا تَجزُّونها بأيديكم وتدبون كالحشرات على أديم الأرض.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الله قد وضع في قلوبكم بذور السعادة فكيف تنتزعونها وتطرحونها على الصخر لتلتقطها الغربان وتذريها الأرياح.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "منذ البدء وظلام الليل يخيم على أرواحنا فأي متى يجيء الفجر؟ من الحبوس إلى الحبوس تنتقل أجسادنا والأجيال تمر بنا ساخرة فإلى متى نحتمل سخرية الأجيال؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "بخُبْثِهِم واحتيالهم قد فرّقوا بين العشيرة والعشيرة وأبعدوا الطائفة عن الطائفة، وبَغَّضُوا القبيلة بالقبيلة، فحتى متى نتبدد كالرماد أمام هذه الزوبعة القاسية، ونتصارع كالأشبال الجائعة بقرب هذه الجيفة المنتنة؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أصغي أيتها الحرية واسمعينا، التفتي يا أم ساكني الأرض وانظرينا فنحن لسنا أبناء ضرَّتِك، تكلمي بلسان فرد واحد منا، فمن شرارة واحدة يشتعل القش اليابس.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أيّ فتى لا يذكر الصبيَّة الأولى التي أبدلت غفلة شبيبته بيقظة هائلة بلطفها، جارحة بعذوبتها، فتَّاكة بحلاوتها؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "لللآبة أيدٍ حريرية الملامس قوية الأعصاب، تقبض على القلوب وتؤلمها بالوحدة، فالوحدة حليفة الكآبة، كما أنها أليفة كل حركة روحية.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "الربيع جميل في كل مكان، ولكنه أكثر من جميل في سوريا ... الربيع روح إله غير معروف تطوف في الأرض مسرعة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الجمال سر تفهمه أرواحنا وتفرح به وتنمو بتأثيراته، أما أفكارنا فتقف أمامه محتارة محاولة تحديده وتجسيده بالألفاظ، ولكنها لا تستطيع.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن المرأة التي تمنحها الآلهة جمال النفس مشفوعًا بجمال الجسد هي حقيقة ظاهرة غامضة نفهمها بالمحبة ونلمسها بالطهر، وعندما نحاول وصفها بالكلام تختفي عن بصائرنا وراء ضباب الحيرة والالتباس.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "بأية ألفاظ نقدر أن نصور وجهًا حزينًا هادئًا محجوبًا وليس محجوبًا بنقاب من الاصفرار الشفاف؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن النفس الحزينة المتألمة تجد راحة بانضمامها إلى نفس أخرى تماثلها بالشعور وتشاركها بالإحساس، مثلما يستأنس الغريب بالغريب في أرض بعيدة عن وطنهما.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "هل هو الكلام الذي يحدث التفاهم بين الأرواح المتحابّة؟ هل هي الأصوات والمقاطع الخارجة من الشفاه والألسنة التي تقرب بين القلوب والعقول؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "كل شيء عظيم وجميل في هذا العالم يتولَّد من فكر واحد أو من حاسة واحدة في داخل الإنسان.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "فِكر واحد يجيئك في سكينة الليل يسير بك إلى المجد أو إلى الجنون.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "تتغير الأشياء أمام أعيننا بتغيُّر عواطفنا، وهكذا نتوهم الأشياء متَّشِحة بالسحر والجمال عندما لا يكون السحر والجمال إلا في نفوسنا.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "ما أجهل الناس الذين يتوهَّمون أن المحبة تتولد بالمعاشرة الطويلة والمرافقة المستمرة. إن المحبة الحقيقية هي ابنة التفاهم الروحي، وإن لم يتم هذا التفاهم بلحظة واحدة لا يتم بعام ولا بجيل كامل.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن حياة الإنسان يا سلمى لا تبتدئ في الرحم، كما أنها لا تنتهي أمام القبر، وهذا الفضاء الواسع المملوء بأشعة القمر والكواكب لا يخلو من الأرواح المتعانقة بالمحبة والنفوس المتضامنة بالتفاهم.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن دمعة واحدة تتلمع على وجنة شيخ متجعدة لهي أشد تأثيرًا في النفس من كل ما تهرقه أجفان الفتيان.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "كل ما يفعله الإنسان سرًّا في ظلمة الليل يظهره الإنسان علنًا في نور النهار. الكلمات التي تهمسها شفاهنا في السكينة تصير على غير معرفة منا حديثًا عموميًّا، والأعمال التي نحاول اليوم إخفاءها في زاويا المنازل تتجسّم غدًا، وتنتصب في منعطفات الشوارع.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن أموال الآباء تكون في أكثر المواطن مجلبة لشقاء البنين؛ تلك الخزائن الواسعة التي يملأها نشاط الوالد وحرص الأم تنقلب حبوسًا ضيقة مظلمة لنفوس الورثة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الملامح التي تُبيح أسرار الذات المعنوية تكسب الوجه جمالًا وملاحة مهما كانت تلك الأسرار موجعة وأليمة، أما الوجوه التي لا تتكلم بصمتها عن غوامض النفس وخفاياها فلا تكون جميلة مهما كانت متناسقة الخطوط متناسبة الأعضاء.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن ظمأ الروح أعذب من ارتواء المادة، وخوف النفس أحب من طمأنينة الجسد.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن قلب المرأة لا يتغير من الزمن ولا يتحول مع الفصول، قلب المرأة ينازع طويلًا، ولكنه لا يموت.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "ماذا فعلت المرأة يا رب فاستحقّت غضبك؟! ماذا أتت من الذنوب ليتبعها سخطك إلى آخر الدهور؟! هل اقترفت جرمًا لا نهاية لفظاعته ليكون عقابك لها بغير نهاية؟!", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أليست المرأة الضعيفة هي رمز الأمة المظلومة؟ أليست المرأة المتوجِّعة بين ميول نفسها وقيود جسدها هي كالأُمَّة المتعذّبة بين حكامها وكهانها؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن النفس الكئيبة تجد راحة بالعزلة والانفراد فتهجر الناس مثلما يبتعد الغزال الجريح عن سربه ويتوارى في كهفه حتى يبرأ أو يموت.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن عذاب النفس بثباتها أمام المصاعب والمتاعب لهو أشرف من تقهقرها إلى حيث الأمن والطمأنينة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "كل شيء في الطبيعة يرمز ويتكلم عن الأمومة، فالشمس هي أم هذه الأرض ترضعها حرارتها وتحتضنها بنورها، ولا تغادرها عند المساء إلا بعد أن تنوّمها على نغمة أمواج البحر وترنيمة العصافير والسواقي.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الكتّاب والشعراء يحاولون إدراك حقيقة المرأة، ولكنهم للآن لم يفهموا أسرار قلبها ومخبّآت صدرها، لأنهم ينظرون إليها من وراء نقاب الشهوات، فلا يرون غير خطوط جسدها، أو يضعونها تحت مكبرات الكره، فلا يجدون فيها غير الضعف والاستسلام.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الرجل يشتري المجد والعظمة والشهرة، ولكن هي المرأة التي تدفع الثمن.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الجامعة البشرية قد استسلمت سبعين قرنًا إلى الشرائع الفاسدة، فلم تعد قادرة على إدراك معاني النواميس العلوية الأولية الخالدة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن السجين المظلوم الذي يستطيع أن يهدم جدران سجنه ولا يفعل يكون جبانًا.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن من لا تلسعه أفاعي الأيام وتنهشه ذئاب الليالي يظل مغرورًا بالأيام والليالي.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "هل وهبنا الله نسمة الحياة لنضعها تحت أقدام الموت؟ وأعطانا الحرية لنجعلها ظلًّا للاستعباد؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أمامنا الحياة وما في الحياة من الحرية وما في الحرية من الغبطة والسعادة، فلماذا لا نخلع النير الثقيل عن عاتقينا ونكسر القيود الموثقة بأرجلنا، ونسير إلى حيث الراحة والطمأنينة؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الإنسان وإن وُلد حرًّا يظل عبدًا لقساوة الشرائع التي سنها آباؤه وأجداده، وأن القضاء الذي نتوهمه سرًّا علويًّا هو استسلام اليوم إلى مآتي الأمس، وخضوع الغد إلى ميول اليوم.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "والمرأة العاقر مكروهة في كل مكان؛ لأن الأنانية تصور لأكثر الرجال دوام الحياة في أجساد الأبناء، فيطلبون النسل ليظلُّوا خالدين على الأرض.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الشجرة التي تنبت في الكهف لا تعطي ثمرا، وسلمى كرامة كانت في ظل الحياة .", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "حياة قصرية ابتدأت بنهاية الليل وانقضت بابتداء النهار، فكانت مثل قطرة الندى التي تسكبها أجفان الظلام ثم تجففها ملامس النور.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أنا لا أبدِّل أحزان قلبي بأفراح الناس، ولا أرضى أن تنقلب الدموع التي تستدرها الكآبة من جوارحي وتصير ضحكًا، أتمنَّى أن تبقى حياتي دمعة وابتسامة، دمعة تطهر قلبي وتفهمني أسرار الحياة وغوامضها، وابتسامة تدنيني من أبناء بجدتي وتكون رمز تمجيدي الآلهة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أريد أن أموت شوقًا ولا أحيا مللًا، أريد أن تكون في أعماق نفسي مجاعة للحب والجمال؛ لأني نظرت فرأيت المستكفئين أشقى الناس وأقربهم من المادة، وأصغيت فسمعت تنهدات المشتاق المتمني أعذب من رنات المثاني والمثالث.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "تعالَ يا موت وأنقذني، فالأرض التي تخنق أشواكها أزهارها لا تصلح للسكن، هلم وخلصني من أيام تخلع الحب عن كرسي مجده وتقيم الشرف العالي مكانه، خلصني يا موت فالأبدية أجدر ببقاء المحبِّين من هذا العالم.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "تعالي أيتها المنية الجميلة فقد اشتاقتك نفسي، اقتربي وحلي قيود المادة فقد تعبتُ من جَرِّهَا، تعالَي إلي يا أيتها المنية الحارة وأنقذيني من بين البشر الذين يحسبونني غريبًا عنهم لأني أترجم ما أسمعه من الملائكة إلى لغة البشر.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أصغوا لأنغام الطيور، وحفيف الأغصان، وخرير الجدول، إن الجمال قسمة السامعين، انظروا وداعة الطفل، وظُرْفَ الشاب، وقُوَّةَ الكهل، وحكمة الشيخ، إن الجمال فتنة الناظرين.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "حقيقة الحياة حياة، حياة لم يكن ابتداؤها في الرحم ولن يكون منتهاها في اللحد، وما هذه السنوات إلا لحظة من حياة أزلية أبدية، هذا العمر الدنيوي مع كل ما فيه هو حلم بجانب اليقظة التي ندعوها الموت المخيف.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "مثلما تكتسب الزهرة عطرها وحياتها من التراب، كذلك تستخلص النفس من ضعف المادة وخطاها قوة وحكمة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "لا تحفظ الأبدية إلا المحبة لأنها مثلها.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أنت يا نفس تفرحين بالآخرة قبل مجيء الآخرة، وهذا الجسد يشقى بالحياة وهو في الحياة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أنت يا نفس غنية بحكمتك وهذا الجسد فقير بسليقته، فلا أنت تتساهلين ولا هو يتبع، وهذا أقصى الشقاء.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "الطبيعة تريد أن تَعِظَ الإنسان مُظْهِرَةً عظمتها تجاه صغره، وقوتها بجانب ضعفه، لا تخف يا ولدي فمن وراء الثلوج المتساقطة والغيوم المتلبدة والأرياح العاصفة روح قدُّوس كلي عالم بما تحتاجه الحقول والآكام.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "ما أخذت منك يا سوريا إلا بعض عطاياي، وما كنت ناهبًا قط بل مستعيرًا أرد، ووفيًّا أرجع، واعلمي أن لأخواتك الأمم نصيبًا باستخدام مجدٍ كان عبدك، وحقًّا بلبس رداء كان لك.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "وبعد سكينة مازجتها الأحلام اللطيفة سألتها: «ما هذا الجمال؟ فقد تباين الناس بتعريفه ومعرفته مثلما اختلفوا بتمجيده ومحبته».", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أنت تريد أيها الْبَشَرِي أن ترى هذا العالم بعين إله، وتريد أن تفقه مكنونات العالم الآتي بفكرة بشرية وهذا منتهى الحماقة، اذهب إلى الْبَرِّيَّةِ تجد النحلة حائمة حول الزهور، والنسر ينقضُّ على الفريسة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "تمر الليالي ونحن غافلون، وتصافحنا الأيام ونحن خائفون من الليالي والأيام، نقترب من التراب والآلهة تنتمي إلينا، ونمر على خبز الحياة والمجاعة تتغذى من قوانا، فما أحب الحياة إلينا وما أبعدنا عن الحياة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "يا من وُلِدْتَ على مهد الشقاء، ورُبِّيتَ في أحضان الذل، وشببت في منازل الاستبداد، أنت الذي تأكل خبزك اليابس بالتنهد، وتشرب ماءك العكر ممزوجًا بالدموع والعبرات.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أنتم يا أحبابي الضعفاء شهداء شرائع الإنسان، أنتم تعساء وتعاستكم نتيجة بغي القوي وجور الحاكم وظلم الغني وأنانية عبد الشهوات.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "لا تقنطوا، فمن مظالم هذا العالم، من وراء المادة من وراء الغيوم، من وراء الأثير، من وراء كل شيء، قوة هي كل عدل وكل شفقة وكل حنو وكل محبة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "ولما فَصَلْتُ تصوراتي بيني وبين البشريات، وأراحت تخيلاتي برقع المادة عن ذاتي المعنوية، شعرت بنور روحي يقربني من الطبيعة ويبين لي غوامض أسرارها ويفهمني لغة مبتدعاتها.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "طلعت الشمس من وراء الجبل وتوَّجت رءوس الأشجار بأكاليل ذهبية، وأنا أسأل ذاتي لماذا يهدم الإنسان ما تبنيه الطبيعة؟!", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "قد كثر المتفرِّجون المستحسنون وقلَّ من تأمل وعقل.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "الشعر يا قوم روح مقدسة متجسمة من ابتسامة تحيي القلب أو تنهدة تسرق من العين مدامعها، أشباح مسكنها النفس وغذاؤها القلب ومشربها العواطف، وإن جاء الشعر على غير هذه الصور فهو كمسيح كَذَّابٍ نَبْذُهُ أَوْقَى.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "من وراء المستقبل رأيت الجموع ساجدة على صدر الطبيعة متجهة نحو المشرق، منتظرة فيض نور الصباح: صباح الحقيقة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "من وراء جدران الحاضر، على مرسح الأجيال الآتية رأيت الجمال عروسًا والنفس عروسة، والحياة كلها ليلة القدر.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "دعني يا لائمي ووحدتي، أستحلفك بحب يضم نفسك بجمال الرفيقة، ويوثق قلبك بحنو الأم، ويربط فؤادك بعواطف الابن، أن تتركني وحالي.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "خلِّنِي وشأني وأحلامي واصبر إلى الغد، فالغد يقضي علي بما يشاء.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أعتقني من حكاية المال وقصص المجد؛ لأن نفسي غنية باكتفائها ومشغولة بمجد الآلهة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أعتقني من مآتي السياسة وأخبار السلطة؛ لأن الأرض كلها وطني، وجميع البشر مواطني.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "آه ما أعظم الحب، وما أصغرني!", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أول نظرة؛هي الدقيقة الفاصلة بين نشوة الحياة ويقظتها، هي الشعلة الأولى التي تنير خلايا النفس، هي أول رنَّة سحرية على أول وتر من قيثارة القلب البشري.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أول قبلة؛هي الرشفة الأولى من كأس ملأتها الآلهة من كوثر الحب، هي الحد بين شك يراود القلب فيحزنه ويقين فيغبطه، هي مطلع قصيدة الحياة الروحية والفصل الأول من رواية الإنسان المعنوي.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "القران؛ها هنا يبتدئ الحب أن ينظم نثر الحياة وينشئ من معانى العمر سُوَرًا ترتلها الأيام وتنغمها الليالي، ها هنا يزيح الشوق ستائر الأشكال عن معميات السنين الماضية، ويؤلِّف من نتف اللذات سعادة لا يفوقها غير سعادة النفس عندما تعانق ربها.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن حياة الأمم يا حبيبتي مثل حياة الأفراد، حياة يؤاخيها الأمل، ويقارنها الخوف، وتحف بها الأماني، ويرمقها القنوط.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "وتعانق الحبيبان وشربا من كئوس القُبَلِ رحيقًا عطرًا، فمرت أجواق الأرواح منشدة: قدوس قدوس قدوس! المحبة مجدها ملء السماء والأرض.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "على أنني وجدت بين هذه النكبات المخيفة والرزايا الهائلة، ألوهية الإنسان واقفة كالجبار تسخر بحماقة الأرض وغضب العناصر، ومثل عمود نور منتصبة بين خرائب بابل ونينوى وتدمر وبمباي وسان فرنسيسكو، ترتل أنشودة الخلود قائلة: لتأخذ الأرض ما لها فلا نهاية لي.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "ولما حلَّق الموت في الجو نظر نحو العالم ونفخ في الهواء هذه الكلمات: «ولن يرجع إلى الأبدية إلا من جاء من الأبدية».", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "ودقيقة تتراوح بين تأثيرات الجمال وأحلام الحب لهي أسمى وأثمن من جبل ملأه المجد الذي يمنحه الضعيف المسكين للقوي الطامع.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "وهذه هي الحياة، تمثلها الليالي على ملعب الدهر نظير مأساة، وتنشدها الأيام كأغنية، وفي النهاية تحفظها الأبدية كجوهرة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "لو علمت يا خليلي الفقير أن الفاقة التي تقضي عليك بالشقاء هي هي التي توحي إليك معرفة العدل وتبثك إدراك كُنْهِ الحياة، لرضيت بقسمة الله.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "إن الساعة التي تصرفها أيها الفقير، مع رفيقتك وصغارك بعد مجيئك من الحقل، لهي رمز العائلة البشرية المستقبلة، هي عنوان سعادة الأجيال الآتية، والحياة التي يصرفها المثري بين الخزائن لهي حياة دنية تحاكي حياة الدود في القبور، هي رمز الخوف.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "سوف تتعلم الأجيال الآتية المساواة من الفقر، والمحبة من الأحزان.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "«سامحيني يا حبيبتي فقد ناجيتك بضمير المخاطب، وأنت نصفي الجميل الذي فقدته عندما خرجنا من يد الله في أن واحد، سامحيني يا حبيبتي».", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أنا يا ابن آدم حيوان ضعيف، ولكني وجدت نسبة كائنة بيني وبين الكثيرين من إخوانك البشر، الذين إذا ما ضعفت قواهم قلَّ رزقهم وساء حالهم.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "حلقة توصل بين هذا العالم والآتي، منهل عذب تستقي منه النفوس العاطشة، شجرة مغروسة على ضفة نهر الجمال ذات ثمار يانعة تطلبها القلوب الجائعة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "قد أحببت الموت مرات عديدة، فدعوته بأسماء عذبة أتشبَّب به سرًّا وعلنًا، ولئن لم أرسل الموت ولا نقضت له عهدًا فإنني صرت أحب الحياة أيضًا، فالموت والحياة قد تساويا عندي بالجمال، وتضارعًا باللذة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "تَمُرِّينَ آنًا فرحة مترنحة، وآونةً متأوهة نادبة، فنسمعك ولا نشاهدك، ونشعر بك ولا نراك، فإنك بحر من الحب يغمر أرواحنا ولا يغرقها، ويتلاعب بأفئدتها وهي ساكنة.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "دعوني أنم فقد سكرت نفسي بالمحبة، دعوني أرقد فقد شبعت روحي من الأيام والليالي، أشعلوا الشموع وأوقدوا المباخر حول مضجعي، وانثروا أوراق الورد والنرجس على جسدي، وعفِّرُوا بالمسك المسحوق شعري، وأهرقوا الطيوب على قدمي.", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "من يجمع بين قواصف البحر وتغريدة البلبل، ويقرن العواصف بتنهدة الطفل، أي بَشَرِيٍّ ينشد أغنية الآلهة؟", Author = "جبران خليل جبران" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/جبران_خليل_جبران", Text = "أنا والشاطئ عاشقان، يرقبهما الهوى ويفصلهما الهواء، أجيء من وراء الشفق الأزرق كيما أمزج فضة زبدي بذهب ماله، وأبرد حرارة قلبه برضابي، عند الفجر أتلو شرع الغرام على مسامع حبيبي فيضمني إلى صدره، وفي المساء أترنم بصلاة الشوق فيقبلني.", Author = "جبران خليل جبران" },
        };
    }
}